//! Blueprint recipes, experimentals and module / ship names from `data/catalog/engineering.json`
//! (generated by `scripts/gen-engineering.py` from EDCD/coriolis-data and EDCD/FDevIDs).
//!
//! Lookups are case-insensitive: the journal writes `FSD_LongRange` and `special_fsd_heavy`, and
//! module items in mixed case.

use serde::Deserialize;
use std::collections::{BTreeMap, HashMap};

#[derive(Debug, Deserialize)]
pub struct Catalog {
    pub source: String,
    pub blueprints: BTreeMap<String, Blueprint>,
    pub experimentals: BTreeMap<String, Experimental>,
    pub groups: BTreeMap<String, Group>,
    pub modules: HashMap<String, ModuleInfo>,
    pub ships: HashMap<String, String>,
}

#[derive(Debug, Deserialize)]
pub struct Blueprint {
    pub name: String,
    pub grades: Vec<GradeRecipe>,
}

#[derive(Debug, Deserialize)]
pub struct GradeRecipe {
    pub grade: u8,
    /// Material id (as in `astromech_materials::catalog`) → count per roll.
    pub materials: BTreeMap<String, i64>,
    #[serde(default)]
    pub engineers: Vec<String>,
}

#[derive(Debug, Deserialize)]
pub struct Experimental {
    pub name: String,
    pub materials: BTreeMap<String, i64>,
}

#[derive(Debug, Deserialize)]
pub struct Group {
    pub name: String,
    pub blueprints: Vec<String>,
    pub experimentals: Vec<String>,
}

#[derive(Debug, Deserialize)]
pub struct ModuleInfo {
    pub group: String,
    pub name: String,
    pub class: Option<u8>,
    pub rating: Option<String>,
    pub mount: Option<String>,
}

impl Blueprint {
    pub fn max_grade(&self) -> u8 {
        self.grades.iter().map(|g| g.grade).max().unwrap_or(0)
    }

    pub fn grade(&self, g: u8) -> Option<&GradeRecipe> {
        self.grades.iter().find(|r| r.grade == g)
    }
}

impl ModuleInfo {
    /// "5A Frame Shift Drive", "2E Pulse Laser (gimballed)", "Military Grade Composite".
    pub fn display(&self) -> String {
        let size = match (self.class, self.rating.as_deref()) {
            (Some(c), Some(r)) if self.group != "bh" => format!("{c}{r} "),
            _ => String::new(),
        };
        let mount = match self.mount.as_deref() {
            Some("F") => " (fixed)",
            Some("G") => " (gimballed)",
            Some("T") => " (turreted)",
            _ => "",
        };
        format!("{size}{}{mount}", self.name)
    }
}

struct Index {
    blueprints: HashMap<String, String>,
    experimentals: HashMap<String, String>,
}

pub fn catalog() -> &'static Catalog {
    static C: std::sync::OnceLock<Catalog> = std::sync::OnceLock::new();
    C.get_or_init(|| {
        serde_json::from_str(include_str!("../../../data/catalog/engineering.json")).expect("engineering.json")
    })
}

fn index() -> &'static Index {
    static I: std::sync::OnceLock<Index> = std::sync::OnceLock::new();
    I.get_or_init(|| {
        let c = catalog();
        Index {
            blueprints: c.blueprints.keys().map(|k| (k.to_ascii_lowercase(), k.clone())).collect(),
            experimentals: c.experimentals.keys().map(|k| (k.to_ascii_lowercase(), k.clone())).collect(),
        }
    })
}

/// Canonical id and data for a blueprint name from the journal or the UI.
pub fn blueprint(name: &str) -> Option<(&'static str, &'static Blueprint)> {
    let id = index().blueprints.get(&name.to_ascii_lowercase())?;
    catalog().blueprints.get_key_value(id).map(|(k, v)| (k.as_str(), v))
}

pub fn experimental(name: &str) -> Option<(&'static str, &'static Experimental)> {
    let id = index().experimentals.get(&name.to_ascii_lowercase())?;
    catalog().experimentals.get_key_value(id).map(|(k, v)| (k.as_str(), v))
}

pub fn module(item: &str) -> Option<&'static ModuleInfo> {
    catalog().modules.get(&item.to_ascii_lowercase())
}

pub fn group(id: &str) -> Option<&'static Group> {
    catalog().groups.get(id)
}

pub fn ship_name(symbol: &str) -> String {
    catalog().ships.get(&symbol.to_ascii_lowercase()).cloned().unwrap_or_else(|| symbol.replace('_', " "))
}
